class Profile { final String targetJob, major, certifications, experience; const Profile({this.targetJob='', this.major='', this.certifications='', this.experience=''}); Map<String,dynamic> toJson()=>{'target_job':targetJob,'major':major,'certifications': certifications.isEmpty?[]:certifications.split(',').map((e)=>e.trim()).toList(),'experience':experience.isEmpty?[]:[experience]}; }
